head.script:
scwin.getTypeGetter = function(info) {
    var rowIndex = info.rowIndex;
    var colIndex = info.colIndex;
    var returnInfo;
    if (rowIndex == 0) {
        returnInfo = {
            id: "dynamic_select01_" + rowIndex + "_" + colIndex,
            inputType: "checkcombobox",
            itemSet: {
                nodeset: "data:ds_combo",
                label: "comm_cd_val_nm",
                value: "comm_cd_val"
            }
        };
    } else {
        returnInfo = {
            id: "dynamic_select01_" + rowIndex + "_" + colIndex,
            inputType: "checkcombobox",
            itemSet: {
                nodeset: "data:ds_combo2",
                label: "comm_cd_val_nm",
                value: "comm_cd_val"
            }
        };
    }
    return returnInfo;
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //-----------------------------------------------
    // 일반이벤트 - 정지일/정지월령 formatting  --var로 선언!!
    //-----------------------------------------------
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
